local P,R,C=game:GetService("Players"),game:GetService("RunService"),workspace.CurrentCamera local L=P.LocalPlayer local E={Box=true,Team=true,Name=true,Dist=true,HPText=true}local O={}
local function isE(p)if p==L or not p.Character then return false end if not E.Team then return true end local m,t=L.Team,p.Team if not m or not t then return true end return m~=t end
R.RenderStepped:Connect(function()for _,p in pairs(P:GetPlayers())do local ch=p.Character local hr=ch and ch:FindFirstChild("HumanoidRootPart")local hd=ch and ch:FindFirstChild("Head")local hm=ch and ch:FindFirstChild("Humanoid")if isE(p)and hr and hd and hm and hm.Health>0 then if not O[p]then O[p]={}O[p].Fill=Drawing.new("Square")O[p].Fill.Filled=true O[p].Fill.Color=Color3.fromRGB(0,0,0)O[p].Fill.Transparency=0.7 O[p].Lines={}for i=1,8 do local l=Drawing.new("Line")l.Thickness=2 O[p].Lines[i]=l end O[p].Name=Drawing.new("Text")O[p].Name.Size=13 O[p].Name.Center=true O[p].Name.Outline=true O[p].Name.Font=2 O[p].Dist=Drawing.new("Text")O[p].Dist.Size=12 O[p].Dist.Center=true O[p].Dist.Outline=true O[p].Dist.Font=2 O[p].HP=Drawing.new("Text")O[p].HP.Size=12 O[p].HP.Center=true O[p].HP.Outline=true O[p].HP.Font=2 end local o=O[p]local hp,on=C:WorldToViewportPoint(hd.Position+Vector3.new(0,0.5,0))local lp=C:WorldToViewportPoint(hr.Position-Vector3.new(0,3,0))if on then local h=math.abs(hp.Y-lp.Y)local w=h/2 local x,y=hp.X-w/2,hp.Y local cw,chh=w*0.2,h*0.15 local dist=(hr.Position-C.CFrame.Position).Magnitude local col=Color3.fromHSV(math.clamp(0.35-(dist/1000),0,0.35),1,1)
o.Fill.Size,o.Fill.Position=Vector2.new(w,h),Vector2.new(x,y)o.Fill.Visible=true
local coords={{x,y,x+cw,y},{x,y,x,y+chh},{x+w,y,x+w-cw,y},{x+w,y,x+w,y+chh},{x,y+h,x+cw,y+h},{x,y+h-chh,x,y+h},{x+w,y+h,x+w-cw,y+h},{x+w,y+h-chh,x+w,y+h}}
for i=1,8 do local l=o.Lines[i]l.From=Vector2.new(coords[i][1],coords[i][2])l.To=Vector2.new(coords[i][3],coords[i][4])l.Color=col l.Visible=true end
local txtCol=Color3.fromRGB(255,255,255)
o.Name.Text=p.Name o.Name.Position=Vector2.new(hp.X,y-18)o.Name.Color=txtCol o.Name.Visible=E.Name
o.Dist.Text=math.floor(dist).."m"o.Dist.Position=Vector2.new(hp.X,y-34)o.Dist.Color=col o.Dist.Visible=E.Dist
o.HP.Text=math.floor(hm.Health).." / "..math.floor(hm.MaxHealth)o.HP.Position=Vector2.new(hp.X,y+h+4)o.HP.Color=Color3.fromHSV(math.clamp(hm.Health/hm.MaxHealth,0,1)*0.3,1,1)o.HP.Visible=E.HPText
else o.Fill.Visible=false for i=1,8 do o.Lines[i].Visible=false end o.Name.Visible=false o.Dist.Visible=false o.HP.Visible=false end elseif O[p]then O[p].Fill.Visible=false for i=1,8 do O[p].Lines[i].Visible=false end O[p].Name.Visible=false O[p].Dist.Visible=false O[p].HP.Visible=false end end end)
P.PlayerRemoving:Connect(function(p)if O[p]then for _,o in pairs(O[p])do if o.Remove then o:Remove()end end O[p]=nil end end)
